 ratios=torch.stack(ratios,1);bits=(ratios>.1).long()+(ratios>.9).long();err=bits!=truth;res=Y[ntrain:]-S[ntrain:]@B;r={'strength':strength,'bit_errors':int(err.sum()),'examples_with_bit_error':int(err.flatten(1).any(1).sum()),'condition_number':float(torch.linalg.cond(B)),'memory_error_norm_rms':float(res.square().sum(1).mean().sqrt()),'weighted_error_rms':float(((res@metric)*res).sum(1).mean().clamp_min(0).sqrt()),'injected_memory_norm_rms':float((S[ntrain:]@B).square().sum(1).mean().sqrt())};strengths.append(r);candidates.append({'B':B,'inverse':inv,'report':r});print('transport',json.dumps(r),flush=True)
